// ═══════════════════════════════════════════════════════════════════════════
// EXPLORE HUB — star map
// SVG map with pan / zoom, colored paths, path selector, signal nodes,
// hover card with "next jump", minimap and keyboard navigation.
// Data: the #exploreData JSON block generated by _layouts/explore-hub.html
// ═══════════════════════════════════════════════════════════════════════════
(function () {
  'use strict';

  const dataEl = document.getElementById('exploreData');
  const mapEl  = document.getElementById('xMap');
  if (!dataEl || !mapEl) return;

  let DATA;
  try { DATA = JSON.parse(dataEl.textContent); }
  catch (err) { console.error('[explore] Could not read map data', err); return; }

  // ── CONFIG ───────────────────────────────────────────────────────────────
  const CFG = {
    spacing: 170,     // distance between two nodes of a path
    jitter: 22,       // max sideways offset of a node from its route
    margin: 240,      // empty space allowed around the content
    kMax: 2.2,        // max zoom
    parallax: 0.45,   // background stars move slower than the nodes
    freeColor: '#7f9cc8',
    levels: { 1: 'BEGINNER', 2: 'INTERMEDIATE', 3: 'ADVANCED' },
    types:  { theory: 'THEORY', lab: 'HANDS-ON LAB', 'write-up': 'WRITE-UP', opinion: 'OPINION' },
  };

  const SVGNS = 'http://www.w3.org/2000/svg';
  const motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
  const reduced = () => motionQuery.matches;

  // ── HELPERS ──────────────────────────────────────────────────────────────
  function hash(str) {
    let h = 2166136261;
    for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
    return h >>> 0;
  }
  // Seeded random → the layout is identical on every visit
  function rngFrom(seed) {
    let s = (seed % 2147483646) + 1;
    return () => { s = (s * 16807) % 2147483647; return (s - 1) / 2147483646; };
  }
  function svgEl(name, attrs, parent) {
    const n = document.createElementNS(SVGNS, name);
    for (const k in attrs) n.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(n);
    return n;
  }
  function hexPoints(r) {
    const pts = [];
    for (let i = 0; i < 6; i++) {
      const a = Math.PI / 3 * i - Math.PI / 6;
      pts.push((r * Math.cos(a)).toFixed(2) + ',' + (r * Math.sin(a)).toFixed(2));
    }
    return pts.join(' ');
  }
  const pad2  = n => String(n).padStart(2, '0');
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const short = (s, n) => (s && s.length > n ? s.slice(0, n - 1) + '…' : s || '');

  // ═════════════════════════════════════════════════════════════════════════
  // MODEL
  // ═════════════════════════════════════════════════════════════════════════
  const PATHS = (DATA.paths || []).map((p, i) => ({
    id: String(p.id),
    name: p.name || p.id,
    color: p.color || '#00e5ff',
    ongoing: p.status === 'ongoing',
    description: p.description || '',
    at: Array.isArray(p.at) ? p.at.map(Number) : [0, i * 380],
    heading: Number(p.heading) || 0,
    wander: p.wander == null ? 30 : Number(p.wander) || 0,
    seed: p.seed == null ? 0 : Number(p.seed) || 0,
    image: p.image || null,
    planned: Array.isArray(p.planned) ? p.planned : [],
    members: [],   // [{ node, step }] sorted by step
  }));
  const PATH = Object.fromEntries(PATHS.map(p => [p.id, p]));
  const NODES = [];

  (DATA.posts || []).forEach(post => {
    const node = {
      kind: 'post', key: post.url, title: post.title, url: post.url, img: post.img,
      tags: post.tags || [], level: post.level, type: post.type, paths: [],
      nudge: Array.isArray(post.nudge) ? post.nudge.map(Number) : null,
    };
    (post.paths || []).forEach(m => {
      const p = m && PATH[m.id];
      if (!p) { if (m) console.warn(`[explore] "${post.title}" uses an unknown path id: "${m.id}"`); return; }
      node.paths.push(p);
      p.members.push({ node, step: Number(m.step) || 999 });
    });
    NODES.push(node);
  });

  // Upcoming entries → "SIGNAL DETECTED" nodes
  PATHS.forEach(p => p.planned.forEach((s, i) => {
    const node = { kind: 'signal', key: `signal:${p.id}:${i}`, title: s && s.title ? String(s.title) : null, paths: [p] };
    p.members.push({ node, step: Number(s && s.step) || 999 });
    NODES.push(node);
  }));

  PATHS.forEach(p => {
    p.members.sort((a, b) => a.step - b.step);
    p.members.forEach((m, i) => { (m.node.pos = m.node.pos || {})[p.id] = i + 1; });
    p.published = p.members.filter(m => m.node.kind === 'post').length;
    p.pending   = p.members.length - p.published;
    const first = p.members.find(m => m.node.kind === 'post');
    if (first) (first.node.startOf = first.node.startOf || []).push(p);
  });

  // ── LAYOUT ── each path starts at `at` and travels roughly toward `heading`.
  // The route is a seeded random walk: the direction drifts a little at every
  // step (`wander`), the distance between nodes varies, and nodes sit a bit
  // off the line. A pull back toward `heading` keeps the path from looping.
  // Same data = same shape on every visit. Change `seed` to reshuffle a path.
  // A post on 2 paths is placed by the first path listed in its front matter.
  PATHS.forEach(p => {
    const rng = rngFrom(hash(p.id) + p.seed * 7919);
    const base = p.heading * Math.PI / 180;
    const w = clamp(p.wander, 0, 80) * Math.PI / 180;
    let ang = base + (rng() - 0.5) * w;
    let x = p.at[0], y = p.at[1];
    p.members.forEach((m, i) => {
      if (i > 0) {
        ang += (rng() - 0.5) * 2 * w;            // drift
        ang += (base - ang) * 0.35;              // pull back toward the heading
        const len = CFG.spacing * (0.88 + rng() * 0.5);
        x += Math.cos(ang) * len;
        y += Math.sin(ang) * len;
      }
      const off = (rng() - 0.5) * CFG.jitter * 2; // small sideways offset
      if (m.node.paths[0] !== p) return;
      m.node.x = x - Math.sin(ang) * off;
      m.node.y = y + Math.cos(ang) * off;
      if (m.node.nudge) { m.node.x += m.node.nudge[0] || 0; m.node.y += m.node.nudge[1] || 0; }
    });
  });

  // Free nodes (no path) float around the paths
  const placed = NODES.filter(n => n.x != null);
  let cx0 = 0, cy0 = 0, R = 0;
  if (placed.length) {
    placed.forEach(n => { cx0 += n.x; cy0 += n.y; });
    cx0 /= placed.length; cy0 /= placed.length;
    placed.forEach(n => { R = Math.max(R, Math.hypot(n.x - cx0, n.y - cy0)); });
  }
  const FREE = NODES.filter(n => n.x == null);
  FREE.forEach(n => {
    const rng = rngFrom(hash(n.key));
    const a = rng() * Math.PI * 2;
    const r = R + 150 + rng() * 240;
    n.x = cx0 + Math.cos(a) * r;
    n.y = cy0 + Math.sin(a) * r * 0.75;
    n.free = true;
  });
  // Push free nodes apart so they don't overlap
  for (let it = 0; it < 40; it++) {
    FREE.forEach(a => NODES.forEach(b => {
      if (a === b) return;
      const dx = a.x - b.x, dy = a.y - b.y, d = Math.hypot(dx, dy) || 1;
      if (d < 90) { const f = (90 - d) / d * 0.5; a.x += dx * f; a.y += dy * f; }
    }));
  }

  if (!NODES.length) { console.warn('[explore] No posts to show'); return; }

  // Map bounds
  const B = { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity };
  NODES.forEach(n => {
    B.minX = Math.min(B.minX, n.x); B.maxX = Math.max(B.maxX, n.x);
    B.minY = Math.min(B.minY, n.y); B.maxY = Math.max(B.maxY, n.y);
  });
  B.minX -= CFG.margin; B.minY -= CFG.margin; B.maxX += CFG.margin; B.maxY += CFG.margin;
  B.w = B.maxX - B.minX; B.h = B.maxY - B.minY;

  // ═════════════════════════════════════════════════════════════════════════
  // RENDER
  // ═════════════════════════════════════════════════════════════════════════
  const svg      = document.getElementById('xSvg');
  const viewport = document.getElementById('xViewport');
  const gFar     = svgEl('g', { class: 'xmap__far' }, svg);
  const gWorld   = svgEl('g', { class: 'xmap__world' }, svg);
  const gRoutes  = svgEl('g', { class: 'xmap__routes' }, gWorld);
  const gNodes   = svgEl('g', { class: 'xmap__nodes' }, gWorld);

  // ── Background stars (parallax layer) ──
  (function stars() {
    const rng = rngFrom(4242);
    const P = CFG.parallax, ex = 1300, ey = 800;
    const x0 = B.minX * P - ex, x1 = B.maxX * P + ex;
    const y0 = B.minY * P - ey, y1 = B.maxY * P + ey;
    const count = Math.min(420, Math.round((x1 - x0) * (y1 - y0) / 11000));
    const pts = [];
    for (let i = 0; i < count; i++) pts.push({ x: x0 + rng() * (x1 - x0), y: y0 + rng() * (y1 - y0), b: rng() });
    // faint mesh between close stars
    const mesh = svgEl('g', { class: 'xmesh' }, gFar);
    pts.forEach((a, i) => {
      let best = null, bd = 140;
      for (let j = i + 1; j < pts.length; j++) {
        const d = Math.hypot(a.x - pts[j].x, a.y - pts[j].y);
        if (d < bd) { bd = d; best = pts[j]; }
      }
      if (best) svgEl('line', { x1: a.x.toFixed(1), y1: a.y.toFixed(1), x2: best.x.toFixed(1), y2: best.y.toFixed(1) }, mesh);
    });
    pts.forEach(s => {
      const o = (0.2 + s.b * 0.7).toFixed(2);
      const c = svgEl('circle', {
        class: 'xstar' + (s.b > 0.82 ? ' xstar--tw' : ''),
        cx: s.x.toFixed(1), cy: s.y.toFixed(1), r: (0.5 + s.b * 1.5).toFixed(2), opacity: o,
      }, gFar);
      if (s.b > 0.82) { c.style.setProperty('--o', o); c.style.animationDelay = (-s.b * 9).toFixed(2) + 's'; }
    });
  })();

  // ── Routes ──
  const ROUTES = [];
  PATHS.forEach(p => {
    for (let i = 0; i < p.members.length - 1; i++) {
      const a = p.members[i].node, b = p.members[i + 1].node;
      const pending = a.kind === 'signal' || b.kind === 'signal';
      const line = svgEl('line', {
        class: 'xroute' + (pending ? ' xroute--pending' : ''),
        x1: a.x.toFixed(1), y1: a.y.toFixed(1), x2: b.x.toFixed(1), y2: b.y.toFixed(1),
      }, gRoutes);
      line.style.setProperty('--c', p.color);
      ROUTES.push({ el: line, path: p });
    }
  });

  // ── Nodes ── DOM order = Tab order: path by path, step by step, then free nodes
  const ordered = [];
  PATHS.forEach(p => p.members.forEach(m => { if (!ordered.includes(m.node)) ordered.push(m.node); }));
  FREE.forEach(n => ordered.push(n));

  function ariaLabel(n) {
    if (n.kind === 'signal') {
      return `Signal detected: upcoming entry in ${n.paths[0].name}` + (n.title ? ` — ${n.title}` : '');
    }
    const bits = [n.title];
    n.paths.forEach(p => bits.push(`${p.name}, step ${n.pos[p.id]} of ${p.members.length}`));
    if (n.startOf) bits.push('recommended starting point');
    if (CFG.levels[n.level]) bits.push(CFG.levels[n.level].toLowerCase());
    if (CFG.types[n.type]) bits.push(CFG.types[n.type].toLowerCase());
    return bits.join(' — ');
  }

  ordered.forEach(n => {
    const primary = n.paths[0];
    const g = n.kind === 'post'
      ? svgEl('a', { href: n.url, class: 'xnode', 'aria-label': ariaLabel(n) }, gNodes)
      : svgEl('g', { class: 'xnode xnode--signal', tabindex: '0', role: 'img', 'aria-label': ariaLabel(n) }, gNodes);
    if (n.free) g.classList.add('xnode--free');
    if (n.startOf) g.classList.add('xnode--start');
    if (n.paths.length > 1) g.classList.add('xnode--junction');
    g.setAttribute('transform', `translate(${n.x.toFixed(1)} ${n.y.toFixed(1)})`);
    g.style.setProperty('--c', primary ? primary.color : CFG.freeColor);

    const r = n.free ? 11 : 19;
    svgEl('polygon', { class: 'xnode__halo', points: hexPoints(r * 1.55) }, g);
    if (n.startOf || n.paths.length > 1) svgEl('polygon', { class: 'xnode__ring', points: hexPoints(r * 1.3) }, g);
    svgEl('polygon', { class: 'xnode__hex', points: hexPoints(r) }, g);
    if (n.free) {
      svgEl('circle', { class: 'xnode__core', r: 2 }, g);
    } else {
      svgEl('text', { class: 'xnode__num', y: 0.5 }, g).textContent =
        n.kind === 'signal' ? '??' : pad2(n.pos[primary.id]);
    }
    if (n.startOf) svgEl('text', { class: 'xnode__badge', y: -r - 14 }, g).textContent = 'START HERE';
    svgEl('text', { class: 'xnode__label', y: r + 18 }, g).textContent =
      n.kind === 'signal' ? 'SIGNAL DETECTED' : short(n.title, 30);

    n.el = g;
    g._node = n;
  });

  // ═════════════════════════════════════════════════════════════════════════
  // CAMERA
  // ═════════════════════════════════════════════════════════════════════════
  const cam = { x: (B.minX + B.maxX) / 2, y: (B.minY + B.maxY) / 2, k: 1 };
  let W = 0, H = 0, kMin = 0.3, anim = 0, ready = false;

  function clampAxis(v, min, max, half) {
    return (max - min) <= 2 * half ? (min + max) / 2 : clamp(v, min + half, max - half);
  }
  function clampCam(c) {
    c.k = clamp(c.k, kMin, CFG.kMax);
    c.x = clampAxis(c.x, B.minX, B.maxX, W / 2 / c.k);
    c.y = clampAxis(c.y, B.minY, B.maxY, H / 2 / c.k);
    return c;
  }
  function applyCamera() {
    if (!W || !H) return;
    gWorld.setAttribute('transform', `translate(${(W / 2 - cam.x * cam.k).toFixed(2)} ${(H / 2 - cam.y * cam.k).toFixed(2)}) scale(${cam.k.toFixed(4)})`);
    const kf = 0.5 + cam.k * 0.5, P = CFG.parallax;
    gFar.setAttribute('transform', `translate(${(W / 2 - cam.x * P * kf).toFixed(2)} ${(H / 2 - cam.y * P * kf).toFixed(2)}) scale(${kf.toFixed(4)})`);
    svg.classList.toggle('is-close', cam.k > 1.15);
    updateMini();
    positionCard();
  }
  function flyTo(target, ms) {
    cancelAnimationFrame(anim);
    clampCam(target);
    if (reduced() || !ms) { Object.assign(cam, target); applyCamera(); return; }
    const from = { ...cam }, t0 = performance.now();
    const step = now => {
      const t = Math.min(1, (now - t0) / ms);
      const e = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
      cam.x = from.x + (target.x - from.x) * e;
      cam.y = from.y + (target.y - from.y) * e;
      cam.k = from.k + (target.k - from.k) * e;
      applyCamera();
      if (t < 1) anim = requestAnimationFrame(step);
    };
    anim = requestAnimationFrame(step);
  }
  function frameFor(nodes) {
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    nodes.forEach(n => { x0 = Math.min(x0, n.x); x1 = Math.max(x1, n.x); y0 = Math.min(y0, n.y); y1 = Math.max(y1, n.y); });
    const k = Math.min((W - 160) / Math.max(1, x1 - x0 + 120), (H - 140) / Math.max(1, y1 - y0 + 120));
    return { x: (x0 + x1) / 2, y: (y0 + y1) / 2, k: clamp(k, 0.6, 1.35) };
  }
  function zoomAt(k, clientX, clientY) {
    const r = viewport.getBoundingClientRect();
    const sx = clientX - r.left, sy = clientY - r.top;
    const wx = cam.x + (sx - W / 2) / cam.k, wy = cam.y + (sy - H / 2) / cam.k;
    cam.k = clamp(k, kMin, CFG.kMax);
    cam.x = wx - (sx - W / 2) / cam.k;
    cam.y = wy - (sy - H / 2) / cam.k;
    clampCam(cam);
    applyCamera();
  }
  function zoomCenter(f) {
    const r = viewport.getBoundingClientRect();
    cancelAnimationFrame(anim);
    zoomAt(cam.k * f, r.left + W / 2, r.top + H / 2);
  }
  function ensureVisible(n) {
    const sx = (n.x - cam.x) * cam.k + W / 2, sy = (n.y - cam.y) * cam.k + H / 2;
    const m = 90;
    if (sx < m || sx > W - m || sy < m || sy > H - m) flyTo({ x: n.x, y: n.y, k: cam.k }, 450);
  }

  // ═════════════════════════════════════════════════════════════════════════
  // PATH SELECTOR
  // ═════════════════════════════════════════════════════════════════════════
  const chipsEl = document.getElementById('xChips');
  const descEl  = document.getElementById('xDesc');
  let activePath = null;
  const activeTags = new Set();   // filled by the keyword filter (bottom of file)
  const chips = [];

  function makeChip(path) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'xchip' + (path ? '' : ' xchip--all');
    b.setAttribute('aria-pressed', 'false');
    if (path) {
      b.style.setProperty('--c', path.color);
      b.innerHTML = '<span class="xchip__dot" aria-hidden="true"></span><span class="xchip__name"></span>' +
        `<span class="xchip__meta">${path.published} ${path.published === 1 ? 'NODE' : 'NODES'}</span>` +
        (path.ongoing ? '<span class="xchip__signal">◉ ONGOING</span>' : '');
      b.querySelector('.xchip__name').textContent = path.name;
    } else {
      b.innerHTML = '<span class="xchip__dot" aria-hidden="true"></span><span class="xchip__name">ALL PATHS</span>';
    }
    b.addEventListener('click', () => setPath(path, true));
    chipsEl.appendChild(b);
    chips.push({ el: b, path });
  }

  function setPath(path, animate) {
    activePath = path;
    chips.forEach(c => c.el.setAttribute('aria-pressed', String(c.path === path)));
    refreshMap();
    mapEl.style.setProperty('--active', path ? path.color : '');

    if (path) {
      const bits = [];
      if (path.description) bits.push(path.description);
      bits.push(`${path.published} ${path.published === 1 ? 'entry' : 'entries'}`);
      if (path.pending) bits.push(`${path.pending} signal${path.pending > 1 ? 's' : ''} pending`);
      descEl.textContent = bits.join(' · ');
    } else {
      descEl.textContent = PATHS.length
        ? 'All known trajectories. Pick one to follow it, or drift freely.'
        : '';
    }
    hideCard(true);
    flyTo(frameFor(path ? path.members.map(m => m.node) : homeNodes()), animate ? 700 : 0);
  }
  // A node matches the keywords when it carries every selected tag
  function matchesTags(n) {
    if (!activeTags.size) return true;
    if (n.kind !== 'post') return false;
    for (const t of activeTags) if (!n.tags.includes(t)) return false;
    return true;
  }
  // Dim = outside the selected path, or not matching the selected keywords
  function refreshMap() {
    const tagsOn = activeTags.size > 0;
    NODES.forEach(n => {
      const inPath = !activePath || n.paths.includes(activePath);
      const match = matchesTags(n);
      n.el.classList.toggle('is-dim', !inPath || !match);
      n.el.classList.toggle('is-match', tagsOn && inPath && match);
    });
    ROUTES.forEach(r => {
      r.el.classList.toggle('is-dim', !!activePath && r.path !== activePath);
      r.el.classList.toggle('is-faint', tagsOn);
    });
  }
  function homeNodes() {
    const inPaths = NODES.filter(n => !n.free);
    return inPaths.length ? inPaths : NODES;
  }

  // ═════════════════════════════════════════════════════════════════════════
  // HOVER / FOCUS CARD
  // ═════════════════════════════════════════════════════════════════════════
  const card     = document.getElementById('xCard');
  const cardImg  = document.getElementById('xCardImg');
  const cardMed  = document.getElementById('xCardMedia');
  const cardPh   = document.getElementById('xCardPh');
  const cardIdx  = document.getElementById('xCardIdx');
  const cardTit  = document.getElementById('xCardTitle');
  const cardBdg  = document.getElementById('xCardBadge');
  const cardMeta = document.getElementById('xCardMeta');
  const cardNext = document.getElementById('xCardNext');
  const cardCta  = document.getElementById('xCardCta');
  let cardNode = null, hideTimer = 0;

  function contextPath(n) {
    return (activePath && n.paths.includes(activePath)) ? activePath : n.paths[0] || null;
  }

  function showCard(n) {
    clearTimeout(hideTimer);
    if (cardNode && cardNode !== n) cardNode.el.classList.remove('is-current');
    cardNode = n;
    n.el.classList.add('is-current');
    const p = contextPath(n);
    card.style.setProperty('--c', p ? p.color : CFG.freeColor);
    card.classList.toggle('xcard--signal', n.kind === 'signal');

    // header line
    if (p) cardIdx.textContent = `NODE_${pad2(n.pos[p.id])} // ${p.name.toUpperCase()}`;
    else   cardIdx.textContent = `FREE SYSTEM${n.tags && n.tags[0] ? ' // ' + String(n.tags[0]).toUpperCase() : ''}`;

    // image
    const img = n.kind === 'post' ? (n.img || (p && p.image) || null) : null;
    cardMed.classList.toggle('is-empty', !img);
    if (img) {
      if (cardImg.getAttribute('src') !== img) {
        cardMed.classList.add('is-loading');
        cardImg.src = img;
      }
    } else cardImg.removeAttribute('src');
    cardPh.textContent = n.kind === 'signal' ? 'SIGNAL INCOMING' : 'NO VISUAL FEED';

    cardTit.textContent = n.kind === 'signal' ? 'SIGNAL DETECTED' : n.title;
    cardBdg.hidden = !(n.startOf && p && n.startOf.includes(p));

    // info layers
    cardMeta.innerHTML = '';
    if (n.kind === 'signal') {
      const s = document.createElement('span');
      s.textContent = n.title ? `Incoming: ${n.title}` : 'Transmission pending. Check back soon.';
      cardMeta.appendChild(s);
    } else {
      if (CFG.levels[n.level]) {
        const lv = document.createElement('span');
        lv.className = 'xcard__level';
        lv.innerHTML = '<span class="xcard__pips" aria-hidden="true">' +
          [1, 2, 3].map(i => `<i class="${i <= n.level ? 'on' : ''}"></i>`).join('') + '</span>';
        lv.append(' ' + CFG.levels[n.level]);
        cardMeta.appendChild(lv);
      }
      if (CFG.types[n.type]) {
        const ty = document.createElement('span');
        ty.textContent = CFG.types[n.type];
        cardMeta.appendChild(ty);
      }
    }
    cardMeta.hidden = !cardMeta.childNodes.length;

    // next jump
    cardNext.removeAttribute('href');
    cardNext.hidden = false;
    if (p) {
      const i = p.members.findIndex(m => m.node === n);
      const next = p.members[i + 1] && p.members[i + 1].node;
      if (!next)                       cardNext.innerHTML = '<b>END OF PATH</b>';
      else if (next.kind === 'signal') cardNext.innerHTML = '<b>NEXT JUMP →</b> signal pending';
      else {
        cardNext.innerHTML = '<b>NEXT JUMP →</b> ';
        cardNext.append(next.title);
        cardNext.href = next.url;
      }
    } else cardNext.hidden = true;

    if (n.kind === 'post') { cardCta.href = n.url; cardCta.hidden = false; }
    else { cardCta.removeAttribute('href'); cardCta.hidden = true; }

    card.classList.add('is-visible');
    positionCard();
  }

  function positionCard() {
    if (!cardNode || !card.classList.contains('is-visible')) return;
    const n = cardNode;
    const sx = (n.x - cam.x) * cam.k + W / 2, sy = (n.y - cam.y) * cam.k + H / 2;
    const cw = card.offsetWidth, ch = card.offsetHeight, gap = 26 * Math.max(0.8, cam.k);
    const top = viewport.offsetTop;
    let x = sx + gap;
    if (x + cw > W - 8) x = sx - gap - cw;
    x = clamp(x, 8, Math.max(8, W - cw - 8));
    const y = clamp(sy - ch / 2, 8, Math.max(8, H - ch - 8));
    card.style.transform = `translate(${x.toFixed(0)}px, ${(y + top).toFixed(0)}px)`;
  }

  function hideCard(now) {
    clearTimeout(hideTimer);
    const go = () => {
      card.classList.remove('is-visible');
      if (cardNode) cardNode.el.classList.remove('is-current');
      cardNode = null;
    };
    if (now) go(); else hideTimer = setTimeout(go, 220);
  }

  // Broken or missing image → placeholder instead of an empty frame
  cardImg.addEventListener('load', () => cardMed.classList.remove('is-loading', 'is-empty'));
  cardImg.addEventListener('error', () => {
    cardMed.classList.remove('is-loading');
    cardMed.classList.add('is-empty');
    if (cardImg.getAttribute('src')) console.warn('[explore] Card image not found:', cardImg.getAttribute('src'));
  });

  card.addEventListener('pointerenter', () => clearTimeout(hideTimer));
  card.addEventListener('pointerleave', () => hideCard());
  card.addEventListener('focusin', () => clearTimeout(hideTimer));
  card.addEventListener('focusout', e => { if (!card.contains(e.relatedTarget)) hideCard(); });

  let lastPointer = 'mouse';
  let dragging = false;
  NODES.forEach(n => {
    n.el.addEventListener('pointerenter', e => { if (e.pointerType !== 'touch' && !dragging) showCard(n); });
    n.el.addEventListener('pointerleave', e => { if (e.pointerType !== 'touch') hideCard(); });
    n.el.addEventListener('focus', () => { ensureVisible(n); showCard(n); });
    n.el.addEventListener('blur', e => { if (!card.contains(e.relatedTarget)) hideCard(); });
    // Touch: first tap shows the card, second tap opens the entry
    n.el.addEventListener('click', e => {
      if (lastPointer === 'touch' && cardNode !== n) { e.preventDefault(); showCard(n); }
    });
  });

  // ═════════════════════════════════════════════════════════════════════════
  // POINTER: drag to pan, pinch / ctrl+wheel to zoom
  // ═════════════════════════════════════════════════════════════════════════
  const pointers = new Map();
  let drag = null, pinch = null, suppressClick = false;

  function pinchState() {
    const [a, b] = [...pointers.values()];
    return { d: Math.hypot(a.x - b.x, a.y - b.y) || 1, mx: (a.x + b.x) / 2, my: (a.y + b.y) / 2 };
  }

  viewport.addEventListener('pointerdown', e => {
    lastPointer = e.pointerType;
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    suppressClick = false;
    cancelAnimationFrame(anim);
    pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pointers.size === 1) {
      drag = { x: e.clientX, y: e.clientY, cx: cam.x, cy: cam.y, moved: false };
    } else if (pointers.size === 2) {
      pinch = { ...pinchState(), k: cam.k };
      if (drag) drag.moved = true;
    }
  });

  viewport.addEventListener('pointermove', e => {
    if (!pointers.has(e.pointerId)) return;
    pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pinch && pointers.size >= 2) {
      const s = pinchState();
      zoomAt(pinch.k * s.d / pinch.d, s.mx, s.my);
      return;
    }
    if (!drag) return;
    const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
    if (!drag.moved && Math.hypot(dx, dy) > 5) {
      drag.moved = true;
      dragging = true;
      viewport.classList.add('is-dragging');
      try { viewport.setPointerCapture(e.pointerId); } catch (_) { /* ignore */ }
      hideCard(true);
    }
    if (drag.moved) {
      cam.x = drag.cx - dx / cam.k;
      cam.y = drag.cy - dy / cam.k;
      clampCam(cam);
      applyCamera();
    }
  });

  function endPointer(e) {
    if (!pointers.has(e.pointerId)) return;
    pointers.delete(e.pointerId);
    if (drag && drag.moved) suppressClick = true;
    if (pointers.size < 2) pinch = null;
    if (pointers.size === 1) {          // one finger left after a pinch → continue panning from here
      const [p] = [...pointers.values()];
      drag = { x: p.x, y: p.y, cx: cam.x, cy: cam.y, moved: true };
    }
    if (pointers.size === 0) {
      drag = null; dragging = false;
      viewport.classList.remove('is-dragging');
    }
  }
  viewport.addEventListener('pointerup', endPointer);
  viewport.addEventListener('pointercancel', endPointer);

  // A drag that ends on a node must not open it
  viewport.addEventListener('click', e => {
    if (suppressClick) { e.preventDefault(); e.stopPropagation(); suppressClick = false; }
  }, true);

  const hint = document.getElementById('xHint');
  let hintTimer = 0;
  function flashHint() {
    hint.classList.add('is-visible');
    clearTimeout(hintTimer);
    hintTimer = setTimeout(() => hint.classList.remove('is-visible'), 1600);
  }

  // Plain scroll keeps scrolling the page; Ctrl/⌘ + scroll (or trackpad pinch) zooms
  viewport.addEventListener('wheel', e => {
    if (!(e.ctrlKey || e.metaKey)) { flashHint(); return; }
    e.preventDefault();
    cancelAnimationFrame(anim);
    const unit = e.deltaMode === 1 ? 0.04 : 0.0012;
    zoomAt(cam.k * Math.exp(-e.deltaY * unit), e.clientX, e.clientY);
  }, { passive: false });

  // ── Keyboard ──
  viewport.addEventListener('keydown', e => {
    const step = 90 / cam.k;
    let handled = true;
    switch (e.key) {
      case 'ArrowLeft':  cam.x -= step; break;
      case 'ArrowRight': cam.x += step; break;
      case 'ArrowUp':    cam.y -= step; break;
      case 'ArrowDown':  cam.y += step; break;
      case '+': case '=': zoomCenter(1.25); return e.preventDefault();
      case '-': case '_': zoomCenter(0.8);  return e.preventDefault();
      case '0': recenter(); return e.preventDefault();
      case 'Escape': hideCard(true); return;
      default: handled = false;
    }
    if (handled) {
      e.preventDefault();
      cancelAnimationFrame(anim);
      clampCam(cam);
      applyCamera();
    }
  });

  // ── Buttons ──
  function recenter() { flyTo(frameFor(activePath ? activePath.members.map(m => m.node) : homeNodes()), 600); }
  mapEl.querySelectorAll('[data-action]').forEach(b => b.addEventListener('click', () => {
    const a = b.dataset.action;
    if (a === 'zoom-in') zoomCenter(1.3);
    else if (a === 'zoom-out') zoomCenter(1 / 1.3);
    else recenter();
  }));

  // ═════════════════════════════════════════════════════════════════════════
  // MINIMAP
  // ═════════════════════════════════════════════════════════════════════════
  const mini = document.getElementById('xMini');
  let miniView = null;
  if (mini) {
    mini.setAttribute('viewBox', `${B.minX} ${B.minY} ${B.w} ${B.h}`);
    mini.setAttribute('preserveAspectRatio', 'xMidYMid meet');
    PATHS.forEach(p => {
      if (p.members.length < 2) return;
      const pl = svgEl('polyline', {
        class: 'xmini__route',
        points: p.members.map(m => `${m.node.x.toFixed(0)},${m.node.y.toFixed(0)}`).join(' '),
      }, mini);
      pl.style.setProperty('--c', p.color);
    });
    const dotR = Math.max(B.w, B.h) / 110;
    NODES.forEach(n => {
      const c = svgEl('circle', { class: 'xmini__dot', cx: n.x.toFixed(0), cy: n.y.toFixed(0), r: dotR.toFixed(1) }, mini);
      c.style.setProperty('--c', n.paths[0] ? n.paths[0].color : CFG.freeColor);
    });
    miniView = svgEl('rect', { class: 'xmini__view' }, mini);
    mini.addEventListener('click', e => {
      const pt = mini.createSVGPoint();
      pt.x = e.clientX; pt.y = e.clientY;
      const w = pt.matrixTransform(mini.getScreenCTM().inverse());
      flyTo({ x: w.x, y: w.y, k: cam.k }, 450);
    });
  }
  function updateMini() {
    if (!miniView) return;
    const vw = W / cam.k, vh = H / cam.k;
    miniView.setAttribute('x', (cam.x - vw / 2).toFixed(0));
    miniView.setAttribute('y', (cam.y - vh / 2).toFixed(0));
    miniView.setAttribute('width', vw.toFixed(0));
    miniView.setAttribute('height', vh.toFixed(0));
  }

  // ═════════════════════════════════════════════════════════════════════════
  // INIT
  // ═════════════════════════════════════════════════════════════════════════
  function measure() {
    const r = viewport.getBoundingClientRect();
    W = r.width; H = r.height;
    if (!W || !H) return false;
    kMin = clamp(Math.min(W / B.w, H / B.h), 0.25, 0.9);
    return true;
  }

  mapEl.hidden = false;
  document.getElementById('xPaths').hidden = false;

  if (PATHS.length) { makeChip(null); PATHS.forEach(makeChip); }

  const ro = new ResizeObserver(() => {
    if (!measure()) return;
    if (!ready) {
      ready = true;
      setPath(null, false);
      if (activeTags.size) {                 // keywords came from the URL
        applyTags(false);
        const hits = POSTS.filter(matchesTags);
        if (hits.length) flyTo(frameFor(hits), 0);
      }
    }
    else { clampCam(cam); applyCamera(); }
  });
  ro.observe(viewport);

  // Mobile: the map is hidden by CSS, so open the text index instead
  const index = document.getElementById('xIndex');
  const mobile = window.matchMedia('(max-width: 768px)');
  if (index && mobile.matches) index.open = true;

  // ═════════════════════════════════════════════════════════════════════════
  // KEYWORD FILTER
  // Click = toggle a keyword. Several keywords narrow the results (AND).
  // Matching nodes light up on the map, a list appears under the keywords,
  // and the selection is kept in the URL (?tags=SOC,Log%20analysis) so it
  // can be shared. Ctrl/⌘ + click still opens the tags page.
  // ═════════════════════════════════════════════════════════════════════════
  const tagEls   = Array.from(document.querySelectorAll('.xtag[data-tag]'));
  const resBox   = document.getElementById('xResults');
  const resCount = document.getElementById('xResCount');
  const resList  = document.getElementById('xResList');
  const resMap   = document.getElementById('xResMap');
  const resClear = document.getElementById('xResClear');
  const POSTS    = NODES.filter(n => n.kind === 'post');
  const tagCount = el => el.querySelector('.xtag__count');

  tagEls.forEach(el => {
    el.setAttribute('role', 'button');
    el.setAttribute('aria-pressed', 'false');
    el.dataset.total = tagCount(el) ? tagCount(el).textContent : '';
    el.addEventListener('click', e => {
      if (e.ctrlKey || e.metaKey || e.shiftKey || e.button !== 0) return;  // let the browser open the link
      e.preventDefault();
      if (el.getAttribute('aria-disabled') === 'true') return;
      toggleTag(el.dataset.tag);
    });
    el.addEventListener('keydown', e => {
      if (e.key === ' ') { e.preventDefault(); el.click(); }
    });
  });

  function toggleTag(tag) {
    if (activeTags.has(tag)) activeTags.delete(tag); else activeTags.add(tag);
    applyTags(true);
  }

  function applyTags(fromUser) {
    const results = POSTS.filter(matchesTags);
    const on = activeTags.size > 0;

    // Keyword states: selected / count within current results / impossible
    tagEls.forEach(el => {
      const t = el.dataset.tag, sel = activeTags.has(t);
      el.setAttribute('aria-pressed', String(sel));
      const c = tagCount(el);
      if (!on || sel) {
        if (c) c.textContent = el.dataset.total;
        el.removeAttribute('aria-disabled');
        el.classList.remove('is-off');
        return;
      }
      const n = results.filter(p => p.tags.includes(t)).length;
      if (c) c.textContent = n;
      el.classList.toggle('is-off', n === 0);
      if (n === 0) el.setAttribute('aria-disabled', 'true'); else el.removeAttribute('aria-disabled');
    });

    // Results list
    resBox.hidden = !on;
    resList.innerHTML = '';
    if (on) {
      const names = Array.from(activeTags).join(' + ');
      resCount.innerHTML = '';
      const strong = document.createElement('b');
      strong.textContent = names;
      resCount.append(strong, ` → ${results.length} ${results.length === 1 ? 'entry' : 'entries'}`);
      if (!results.length) {
        const li = document.createElement('li');
        li.className = 'xresults__empty';
        li.textContent = 'No entry matches all of these. Remove a keyword to widen the search.';
        resList.appendChild(li);
      }
      results.forEach(n => resList.appendChild(resultItem(n)));
    }
    resMap.hidden = !ready || !results.length;

    refreshMap();
    if (fromUser && ready && results.length) {
      const visible = results.filter(n => !activePath || n.paths.includes(activePath));
      if (visible.length) flyTo(frameFor(visible), 600);
    }
    if (fromUser) saveToUrl();
  }

  function resultItem(n) {
    const li = document.createElement('li');
    li.className = 'xres';
    const p = n.paths[0];
    li.style.setProperty('--c', p ? p.color : CFG.freeColor);

    const a = document.createElement('a');
    a.className = 'xres__link';
    a.href = n.url;

    const top = document.createElement('span');
    top.className = 'xres__where';
    top.textContent = n.paths.length
      ? n.paths.map(q => `${q.name.toUpperCase()} · ${pad2(n.pos[q.id])}`).join('  /  ')
      : 'FREE SYSTEM';
    const title = document.createElement('span');
    title.className = 'xres__title';
    title.textContent = n.title;
    a.append(top, title);

    const meta = document.createElement('span');
    meta.className = 'xres__meta';
    const bits = [];
    if (CFG.levels[n.level]) bits.push(CFG.levels[n.level]);
    if (CFG.types[n.type]) bits.push(CFG.types[n.type]);
    meta.textContent = bits.join(' · ');
    if (bits.length) a.appendChild(meta);

    const tags = document.createElement('span');
    tags.className = 'xres__tags';
    n.tags.forEach(t => {
      const s = document.createElement('span');
      s.textContent = t;
      if (activeTags.has(t)) s.className = 'is-hit';
      tags.appendChild(s);
    });
    a.appendChild(tags);
    li.appendChild(a);

    // Hovering a result highlights its node on the map
    li.addEventListener('pointerenter', () => n.el.classList.add('is-current'));
    li.addEventListener('pointerleave', () => { if (cardNode !== n) n.el.classList.remove('is-current'); });
    return li;
  }

  resClear.addEventListener('click', () => {
    activeTags.clear();
    applyTags(true);
    const first = tagEls[0];
    if (first) first.focus();
  });
  resMap.addEventListener('click', () => {
    mapEl.scrollIntoView({ behavior: reduced() ? 'auto' : 'smooth', block: 'start' });
    viewport.focus({ preventScroll: true });
  });

  function saveToUrl() {
    try {
      const u = new URL(window.location.href);
      if (activeTags.size) u.searchParams.set('tags', Array.from(activeTags).join(','));
      else u.searchParams.delete('tags');
      history.replaceState(null, '', u);
    } catch (_) { /* ignore */ }
  }
  (function loadFromUrl() {
    let raw = null;
    try { raw = new URL(window.location.href).searchParams.get('tags'); } catch (_) { /* ignore */ }
    if (!raw) return;
    const known = new Set(tagEls.map(el => el.dataset.tag));
    raw.split(',').map(s => s.trim()).filter(t => known.has(t)).forEach(t => activeTags.add(t));
    if (activeTags.size) applyTags(false);
  })();
})();
